    scwin.listSync(); //alert();

};

scwin.image_1_onclick = function(e) {
    if (scwin.toDay === scwin.txb_date) {
        scwin.save();
    } else {
        alert("과거일은 조회만 가능합니다.");
    }
};

scwin.MxLogicalTr_save_OnFail = function() {
    scwin.listSync();
};

scwin.MxLogicalTr_save_OnSuccess = function() {
    scwin.listSync();
};

scwin.MxGrid_1_oncheckclick = function(rowIndex, columnIndex, columnId) {
    if (bCheck !== 0) {
        scwin.chk(col);
        //alert('MxGrid_1.OnCheckClick('+col+','+ colid+','+ bCheck+')');

    }
};

scwin.image_2_onclick = function(e) {
    if (scwin.toDay === scwin.txb_date) {
        if (confirm('really?')) scwin.save2();
    } else {
