scwin.save = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_insert",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_insert=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_insert_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    if (!scwin.cntDatasetRowCheck(MxDataSet)) {
        alert('체크사항이 없습니다');
        return;
    }
    let lastch = "Y"; //최종업무확인
    let unitCl = 0;
    // TODO Stage2: 0-based 검토
    for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
        if (MxDataSet.getCellData(i, "CHK_FLAG") === 1) {
            unitCl = i;
        }
    }
    if (unitCl !== 0) {
        MxDataSet.addRow();
        //alert("단위업무마감을 시작합니다.");

        // TODO Stage2: 0-based 검토
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "BAS_DD", MxDataSet.getCellData(unitCl, "BAS_DD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CHK_BZ_TP_CD", MxDataSet.getCellData(unitCl, "CHK_BZ_TP_CD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "UNIT_BZ_CLS_DDTM", "99991231000000");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CLS_TRANSTR_EMP_NO", js_emp_no);
    }
    // TODO Stage2: 0-based 검토
    for (let k = 1; k <= MxDataSet.getRowCount(); k++) {
        if (MxDataSet.getCellData(k, "CHK_BZ_TP_CD") === '40' && MxDataSet.getCellData(k, "UNIT_BZ_CLS_DDTM") === "99991231000000") {
            lastch = "N";
            break;
        }
    }
    if (lastch === "Y") {
        // TODO Stage2: 0-based 검토
        MxDataSet.addRow();
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "BAS_DD", MxDataSet.getCellData(1, "BAS_DD"));
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CHK_BZ_TP_CD", "40");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "UNIT_BZ_CLS_DDTM", "99991231000000");
        MxDataSet.setCellData(MxDataSet.getRowPosition(), "CLS_TRANSTR_EMP_NO", js_emp_no);
    }
    /*

	//----W-Craft WebSquare 변환 확인: AddRow----//
    			MxDataSet_insert.AddRow();

	//----W-Craft WebSquare 변환 확인: NameValue----//
    			MxDataSet_insert.NameValue(1, "BAS_DD") = "20080516";

	//----W-Craft WebSquare 변환 확인: NameValue----//
    			MxDataSet_insert.NameValue(1, "CHK_BZ_TP_CD") = "31";

	//----W-Craft WebSquare 변환 확인: NameValue----//
    			MxDataSet_insert.NameValue(1, "UNIT_BZ_STRT_DDTM") = "20080516090000"

	//----W-Craft WebSquare 변환 확인: NameValue----//
    			MxDataSet_insert.NameValue(1, "UNIT_BZ_CLS_DDTM") = "20080516190000"

	//----W-Craft WebSquare 변환 확인: NameValue----//
    			MxDataSet_insert.NameValue(1, "CLS_TRANSTR_EMP_NO") = "010271";
    */
    //alert(MxDataSet_insert.Text);
    //alert("단위업무의 재시작을 시작합니다\n최종업무가 마감된 경우 최종업무는 개시됩니다");
    const sbmOptions3 = {
        id : "sbm_MxLogicalTr_save",
        action : "/bzchklist.do",
        ref : "MxDataSet",
        target : "MxLogicalTr_save=body.content",
        submitDoneHandler : scwin.sbm_MxLogicalTr_save_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);
};

scwin.save2 = function() {
    alert("금감원 제출, 코스콤공시전송을 제외한 시작되지 않은 모든 업무를 수동시작합니다.");
    // TODO Stage2: 0-based 검토
    for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
        if (MxDataSet.getCellData(i, "BAS_DD") === "" && MxDataSet.getCellData(i, "CHK_BZ_TP_CD").substring(0, 1) !== '2') {
            if (MxDataSet.getCellData(i, "CHK_BZ_TP_CD") !== '51') {
                MxDataSet.setCellData(i, "BAS_DD", scwin.txb_date);
            }
        }
    }

    //alert(MxDataSet.Text);
    const sbmOptions = {
        id : "sbm_MxLogicalTr_save",
        action : "/bzchklist.do",
        ref : "MxDataSet",
        target : "MxLogicalTr_save=body.content",
        submitDoneHandler : scwin.sbm_MxLogicalTr_save_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

scwin.chk = function(sval) {
    // TODO Stage2: 0-based 검토
    if (MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '31' && //유가 공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '32' && //코스닥 공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '33' && //코스닥시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '34' && //주식시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '35' && //ETF시장팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '36' && //예방감시팀(코스닥)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '37' && //예방감시팀(유가)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '39' && //시장감시3팀(ELW)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '38' && //채권상장공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3A' && //코넥스상장공시팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3B' && //코넥스시장운영팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3C' && //예방감시팀(코넥스)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3E' && //예방감시팀(배출권)
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3D' && //ETN시장팀
        MxDataSet.getCellData(sval, "CHK_BZ_TP_CD") !== '3F') {
        alert("재시작 대상업무가 아닙니다.");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    if (MxDataSet.getCellData(sval, "BAS_DD") === '') {
        alert("업무가 시작되지 않았습니다");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    if (MxDataSet.getCellData(sval, "UNIT_BZ_CLS_DDTM") === '99991231000000') {
        alert("업무가 종료되지 않았습니다.");
        MxDataSet.setCellData(sval, "CHK_FLAG", 0);
        return;
    }
    // TODO Stage2: 0-based 검토
    for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
        if (MxDataSet.getCellData(i, "CHK_FLAG") === 1 && i !== sval) MxDataSet.setCellData(i, "CHK_FLAG", 0);
    }
    MxDataSet.setCellData(sval, "CHK_FLAG", 1);
};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    let cCnt = 0;
    // TODO Stage2: 0-based 검토
    for (let i = 1; i <= sval.getRowCount(); i++) {
        //alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) return false;

    else return true;
};

scwin.notEndDocLst = async function() {
    const url = "/jobmonitor/ULDMGT10005.gfm?date=" + tmbDate.getValue();
    // TODO Stage2: 동적 url popup id 확인
    const options = {
        id : "virWinNotEndDocLst",
        title : "미처리 공시 리스트(" + tmbDate.getValue() + ")",
        width : "865px",
        height : "315px"
    };
    const data = {};
    await $c.win.openPopup(url, options, data);
};

scwin.MxGrid_1_CanColumnPosChange = function(row, colid) {
    return true;
};

