    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_MxDataSet_insert",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_insert=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_insert_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


    const sbmOptions3 = {
        id : "sbm_MxDataSet_select",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_select=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_select_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);


    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

    //미승인건 조회 버튼은 18시 이후부터 보이도록 수정 20210528
    if (scwin.vNowHHMM > '1800') {
        image_3.show("");
    } else {
        image_3.hide();
    }
    scwin.listSync();
    //toDaySet(txb_date);

};
